const request = $input.first().json;

/**
 * n8n Webhook requests normally place JSON inside request.body.
 * The fallback also supports manual testing.
 */
let input = request.body ?? request;

if (typeof input === 'string') {
  try {
    input = JSON.parse(input);
  } catch {
    throw new Error(
      'Contact validation failed:\n- The submitted request body is not valid JSON.'
    );
  }
}

if (
  !input ||
  typeof input !== 'object' ||
  Array.isArray(input)
) {
  throw new Error(
    'Contact validation failed:\n- The submitted contact message is invalid.'
  );
}

/**
 * Read the first available value from possible field names.
 */
function getValue(...possibleNames) {
  for (const name of possibleNames) {
    const value = input[name];

    if (
      value !== undefined &&
      value !== null &&
      typeof value !== 'object'
    ) {
      return String(value).trim();
    }
  }

  return '';
}

/**
 * Clean short single-line values.
 */
function cleanSingleLine(value) {
  return String(value ?? '')
    .replace(/\u0000/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Clean multiline message text while keeping useful line breaks.
 */
function cleanMultiline(value) {
  return String(value ?? '')
    .replace(/\u0000/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Escape submitted text before inserting it into an HTML email.
 */
function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const name = cleanSingleLine(
  getValue('name', 'Name')
);

const email = cleanSingleLine(
  getValue('email', 'Email')
).toLowerCase();

const company = cleanSingleLine(
  getValue('company', 'Company')
);

const message = cleanMultiline(
  getValue('message', 'Message')
);

const requestId = cleanSingleLine(
  getValue(
    'request_id',
    'requestId',
    'Request ID'
  )
);

const validationErrors = [];

if (!name) {
  validationErrors.push('Name is required.');
}

if (!email) {
  validationErrors.push('Email is required.');
}

if (!message) {
  validationErrors.push('Message is required.');
}

const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (
  email &&
  !emailPattern.test(email)
) {
  validationErrors.push(
    'Email is not a valid email address.'
  );
}

const lengthLimits = [
  ['Name', name, 150],
  ['Email', email, 255],
  ['Company', company, 200],
  ['Message', message, 5000],
  ['Request ID', requestId, 150],
];

for (const [label, value, maximum] of lengthLimits) {
  if (String(value).length > maximum) {
    validationErrors.push(
      `${label} exceeds the ${maximum}-character limit.`
    );
  }
}

if (validationErrors.length > 0) {
  throw new Error(
    `Contact validation failed:\n- ${validationErrors.join('\n- ')}`
  );
}

const receivedAt = new Date();

const datePart = receivedAt
  .toISOString()
  .replace(/\D/g, '')
  .slice(0, 14);

const randomPart = Math.random()
  .toString(36)
  .slice(2, 7)
  .toUpperCase()
  .padEnd(5, '0');

const contactReference =
  `MSG-${datePart}-${randomPart}`;

const displayCompany =
  company || 'Not provided';

const subject =
  company
    ? `[AdFlow Contact] ${name} — ${company}`
    : `[AdFlow Contact] Message from ${name}`;

const plainTextMessage = [
  'New AdFlow Studio contact message',
  '',
  `Reference: ${contactReference}`,
  `Name: ${name}`,
  `Email: ${email}`,
  `Company: ${displayCompany}`,
  `Received: ${receivedAt.toISOString()}`,
  requestId
    ? `Request ID: ${requestId}`
    : '',
  '',
  'Message:',
  message,
].filter(Boolean).join('\n');

const htmlMessage = `
  <div style="
    font-family: Arial, Helvetica, sans-serif;
    max-width: 680px;
    margin: 0 auto;
    color: #111827;
    line-height: 1.6;
  ">
    <div style="
      background: #0b1020;
      color: #ffffff;
      padding: 24px;
      border-radius: 12px 12px 0 0;
    ">
      <p style="
        margin: 0 0 6px;
        color: #ec4899;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 1.2px;
        text-transform: uppercase;
      ">
        AdFlow Studio
      </p>

      <h1 style="
        margin: 0;
        font-size: 24px;
      ">
        New website contact message
      </h1>
    </div>

    <div style="
      padding: 24px;
      border: 1px solid #e5e7eb;
      border-top: 0;
      border-radius: 0 0 12px 12px;
    ">
      <table style="
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 24px;
      ">
        <tr>
          <td style="
            padding: 8px 0;
            color: #6b7280;
            width: 140px;
          ">
            Reference
          </td>

          <td style="
            padding: 8px 0;
            font-weight: 600;
          ">
            ${escapeHtml(contactReference)}
          </td>
        </tr>

        <tr>
          <td style="
            padding: 8px 0;
            color: #6b7280;
          ">
            Name
          </td>

          <td style="padding: 8px 0;">
            ${escapeHtml(name)}
          </td>
        </tr>

        <tr>
          <td style="
            padding: 8px 0;
            color: #6b7280;
          ">
            Email
          </td>

          <td style="padding: 8px 0;">
            <a href="mailto:${escapeHtml(email)}">
              ${escapeHtml(email)}
            </a>
          </td>
        </tr>

        <tr>
          <td style="
            padding: 8px 0;
            color: #6b7280;
          ">
            Company
          </td>

          <td style="padding: 8px 0;">
            ${escapeHtml(displayCompany)}
          </td>
        </tr>

        <tr>
          <td style="
            padding: 8px 0;
            color: #6b7280;
          ">
            Received
          </td>

          <td style="padding: 8px 0;">
            ${escapeHtml(receivedAt.toISOString())}
          </td>
        </tr>
      </table>

      <div style="
        padding: 18px;
        background: #f9fafb;
        border-radius: 8px;
        white-space: pre-wrap;
      ">${escapeHtml(message)}</div>

      ${
        requestId
          ? `
            <p style="
              margin-top: 20px;
              color: #9ca3af;
              font-size: 12px;
            ">
              Request ID:
              ${escapeHtml(requestId)}
            </p>
          `
          : ''
      }
    </div>
  </div>
`;

return [
  {
    json: {
      success: true,

      contact_reference:
        contactReference,

      name,
      email,
      company,
      display_company:
        displayCompany,

      message,

      request_id:
        requestId,

      received_at:
        receivedAt.toISOString(),

      subject,

      plain_text_message:
        plainTextMessage,

      html_message:
        htmlMessage,
    },
  },
];

